  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f8f9fb;
  --color-surface: #ffffff;
  --color-border: #e2e6ed;
  --color-text-primary: #1a1d23;
  --color-text-secondary: #5a6272;
  --color-accent: #5b6af8;
  --color-accent-hover: #4453e8;
  --color-accent-light: #eef0fe;
  --color-focus-ring: #5b6af8;
  --radius-card: 12px;
  --radius-btn: 8px;
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.07), 0 4px 16px rgba(0, 0, 0, 0.05);
  --transition: 200ms ease;
  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.6;
  min-height: 100dvh;
  padding: 2rem 1rem 4rem;
}

/* ── Page header ── */
.page-header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 3rem;
}

.page-header .badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  margin-bottom: 1rem;
}

.page-header h1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text-primary);
  line-height: 1.2;
  margin-bottom: 0.75rem;
}

.page-header p {
  font-size: 1.0625rem;
  color: var(--color-text-secondary);
  max-width: 42ch;
  margin: 0 auto;
}

/* ── FAQ list ── */
.faq-list {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Individual FAQ item ── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow var(--transition);
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  box-shadow: 0 2px 8px rgba(91, 106, 248, 0.12), 0 6px 24px rgba(0, 0, 0, 0.07);
  border-color: rgba(91, 106, 248, 0.3);
}

/* ── Trigger button ── */
.faq-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.125rem 1.375rem;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
  border-radius: var(--radius-card);
  transition: background var(--transition), color var(--transition);
}

.faq-trigger:hover {
  background: var(--color-accent-light);
  color: var(--color-accent);
}

.faq-trigger:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: -2px;
}

.faq-trigger[aria-expanded="true"] {
  color: var(--color-accent);
  background: var(--color-accent-light);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

/* ── Icon ── */
.faq-icon {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-border);
  border-radius: 50%;
  transition: transform var(--transition), background var(--transition);
}

.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
  background: var(--color-accent);
}

.faq-icon svg {
  display: block;
  fill: var(--color-text-secondary);
  transition: fill var(--transition);
}

.faq-trigger[aria-expanded="true"] .faq-icon svg {
  fill: #fff;
}

/* ── Answer panel ── */
.details {
  overflow: hidden;
  transition: height var(--transition);
}

.details[hidden] {
  display: none;
}

.details-inner {
  padding: 1rem 1.375rem 1.25rem;
  border-top: 1px solid var(--color-border);
  color: var(--color-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

.details-inner p + p {
  margin-top: 0.75rem;
}

/* ── Reflow at 320 px ── */
@media (max-width: 360px) {
  .faq-trigger {
    padding: 1rem;
    font-size: 0.9375rem;
  }
  .details-inner {
    padding: 0.875rem 1rem 1rem;
  }
}

/* ── Forced-colors support ── */
@media (forced-colors: active) {
  .example {
    border-color: ButtonBorder;
  }
  .faq-trigger {
    color: ButtonText;
  }
  .faq-trigger:focus-visible {
    outline: 2px solid ButtonText;
  }
  .faq-icon {
    background: ButtonFace;
    border: 1px solid ButtonBorder;
  }
  .faq-icon svg {
    fill: ButtonText;
  }
}
