+/**
+ * FAQ Disclosure Widget
+ *
+ * Each .example contains:
+ *   button.faq-trigger[aria-expanded][aria-controls]
+ *   div.details[id][hidden]
+ *
+ * Clicking a trigger toggles its panel open/closed with an animated height
+ * transition. Pressing Escape while focus is inside a panel closes it and
+ * returns focus to the trigger.
+ */
+
+class FAQItem {
+  constructor(example) {
+    this.trigger = example.querySelector(".faq-trigger");
+    this.panel = example.querySelector(".details");
+
+    if (!this.trigger || !this.panel) return;
+
+    this.trigger.addEventListener("click", () => this.toggle());
+    this.panel.addEventListener("keydown", (e) => {
+      if (e.key === "Escape") {
+        this.close();
+        this.trigger.focus();
+      }
+    });
+  }
+
+  isOpen() {
+    return this.trigger.getAttribute("aria-expanded") === "true";
+  }
+
+  open() {
+    this.panel.removeAttribute("hidden");
+    // Measure natural height then animate
+    const fullHeight = this.panel.scrollHeight + "px";
+    this.panel.style.height = "0";
+    // Force reflow so the transition fires
+    this.panel.getBoundingClientRect();
+    this.panel.style.height = fullHeight;
+    this.panel.addEventListener(
+      "transitionend",
+      () => {
+        this.panel.style.height = "";
+      },
+      { once: true }
+    );
+    this.trigger.setAttribute("aria-expanded", "true");
+  }
+
+  close() {
+    // Animate from current height to 0
+    this.panel.style.height = this.panel.scrollHeight + "px";
+    this.panel.getBoundingClientRect();
+    this.panel.style.height = "0";
+    this.panel.addEventListener(
+      "transitionend",
+      () => {
+        this.panel.style.height = "";
+        this.panel.setAttribute("hidden", "");
+      },
+      { once: true }
+    );
+    this.trigger.setAttribute("aria-expanded", "false");
+  }
+
+  toggle() {
+    this.isOpen() ? this.close() : this.open();
+  }
+}
+
+function initFAQ() {
+  document.querySelectorAll(".example").forEach((el) => new FAQItem(el));
+}
+
+if (document.readyState === "loading") {
+  document.addEventListener("DOMContentLoaded", initFAQ);
+} else {
+  initFAQ();
+}
